begin;
\ir progression_fixture.sql
-- Use high initial values to test selection grants independently of low-stat penalties.
update public.dcc_crawlers set stat_baseline=(select jsonb_object_agg(key,value||'{"base":20}'::jsonb)from jsonb_each(stat_baseline))where id=current_setting('dcc_test.pg_id')::uuid;
select pg_temp.pg_assert((dcc_private.progression_custom('{"kind":"class","earth":false,"name":"Passive test","description":"","lines":[{"traitId":"skill","target":"catcher","quantity":3},{"traitId":"skill","target":"hot-stuff-aura","quantity":2}]}',(select stat_baseline from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),(select learned_skills from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid))->'issues')='[]'::jsonb,'Five Passive ranks should be legal and cost ten BP.');
select pg_temp.pg_assert((dcc_private.progression_custom('{"kind":"class","earth":false,"name":"Passive test","description":"","lines":[{"traitId":"skill","target":"catcher","quantity":6}]}',(select stat_baseline from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),(select learned_skills from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid))->'issues')?'passive-cap','Six Passive ranks were allowed.');
select pg_temp.pg_error('select dcc_private.progression_custom(''{"kind":"race","earth":true,"name":"Unknown","description":"","lines":[{"traitId":"rank20-group","target":"passive-spell","quantity":1}]}'',''{}'',''[]'')','22023');
savepoint legacy_partial;
update public.dcc_crawlers set third_floor='{"reviewed":false,"offers":[],"selected":null}',advancement=jsonb_set(advancement,'{humanFavor}','true')where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select public.dcc_third_floor_action(current_setting('dcc_test.pg_id')::uuid,(select version from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'partial-review','{"reason":"Human Strength already applied; other benefits missing","confirmed":true}');
select pg_temp.pg_assert((select advancement->>'humanFavor'='true'and advancement->>'spent'='0'and third_floor->>'reviewed'='false'and stat_baseline#>>'{strength,base}'='20'and current_segments=0 and tutorial_profile->>'mana'='2'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Preparing partial review changed grants, resources or legacy Human Favor.');
select pg_temp.pg_act('offer','{"offers":[{"raceId":"human","classId":"blizzardmancer","waivers":[]}]}');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_error('select pg_temp.pg_act(''select'',jsonb_build_object(''offerId'',(select progression#>>''{offers,0,id}''from public.dcc_crawlers where id=current_setting(''dcc_test.pg_id'')::uuid),''choices'',''{}''::jsonb,''split'',''{}''::jsonb,''skip'',''[]''::jsonb))','42501');
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','["human:stat:strength"]'::jsonb));
select pg_temp.pg_assert((select advancement->>'humanFavor'='true'and stat_baseline#>>'{strength,base}'='18'and third_floor#>>'{selected,raceId}'='human'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Partial review repeated an old grant or lost Human Favor.');
rollback to legacy_partial;
savepoint allocation;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select public.dcc_advancement_action(current_setting('dcc_test.pg_id')::uuid,(select version from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'authorize','{"amount":3,"saferoom":true,"reason":"Selection minimum assistance"}');
select pg_temp.pg_act('offer','{"offers":[{"raceId":"human","classId":"blizzardmancer","waivers":[]}]}');
select set_config('dcc_test.pg_before',(select to_jsonb(c)::text from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),true);
select pg_temp.pg_error('select pg_temp.pg_act(''select'',''{"offerId":"missing","choices":{},"split":{},"skip":[],"allocation":{"strength":1,"intelligence":2,"constitution":0,"dexterity":0,"charisma":0}}'')','22023');
select pg_temp.pg_assert((select to_jsonb(c)=current_setting('dcc_test.pg_before')::jsonb from public.dcc_crawlers c where id=current_setting('dcc_test.pg_id')::uuid),'Failed selection did not roll back its allocation.');
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','[]'::jsonb,'allocation','{"strength":1,"intelligence":2,"constitution":0,"dexterity":0,"charisma":0}'::jsonb));
select pg_temp.pg_assert((select advancement->>'spent'='3'and advancement->>'authorized'='0'and stat_baseline#>>'{strength,base}'='21'and stat_baseline#>>'{intelligence,base}'='28'and tutorial_profile->>'mana'='2'and current_segments=0 from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Combined allocation and selection did not conserve points/resources.');
rollback to allocation;
savepoint primal;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_act('evidence','{"evidence":{"facts":{"originalRace":"human","originalSize":4},"popularity":null,"identityLimits":false}}');
select pg_temp.pg_act('offer','{"offers":[{"raceId":"primal","classId":"blizzardmancer","waivers":[]}]}');
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','[]'::jsonb));
select pg_temp.pg_assert((select stat_baseline#>>'{strength,base}'='19'and advancement->>'humanFavor'='true'and progression#>>'{selection,inheritedRace,id}'='human'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Primal original-Race benefits were omitted or duplicated.');
select pg_temp.pg_assert((select bool_and(case when value->>'id'='heal'then value->>'maxRank'='1'else value->>'maxRank'='20'end)from public.dcc_crawlers,lateral jsonb_array_elements(learned_skills)where id=current_setting('dcc_test.pg_id')::uuid),'Primal caps lost or protected Heal modified.');
rollback to primal;
savepoint split_stats;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_act('reward','{"decision":"already-received"}');
select pg_temp.pg_act('offer','{"offers":[{"raceId":"elf-city","classId":"professional-roadie","waivers":[]}]}');
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{"elf-city":{"intelligence":2,"dexterity":2,"charisma":2},"professional-roadie":{"strength":3,"constitution":3,"charisma":2}}'::jsonb,'skip','[]'::jsonb));
select pg_temp.pg_assert((select stat_baseline#>>'{strength,base}'='23'and stat_baseline#>>'{charisma,base}'='24'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Race and Class split pools were mixed.');
rollback to split_stats;
savepoint custom_build;
reset role;
update public.dcc_crawlers set learned_skills=(select jsonb_agg(case when value->>'id'='dagger'then jsonb_set(value,'{rank}','1')else value end)from jsonb_array_elements(learned_skills))where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_act('draft','{"build":{"kind":"race","earth":false,"name":"Tiny Fast Golem","description":"Synthetic custom test","lines":[{"traitId":"stat","target":"strength","quantity":3},{"traitId":"group-penalty","target":"dexterity","quantity":1},{"traitId":"move","target":"","quantity":1},{"traitId":"small","target":"","quantity":1}],"bespoke":[{"name":"Party bell","points":2,"description":"GM-priced table effect"}]}}');
select pg_temp.pg_act('approve',jsonb_build_object('id',(select progression#>>'{definitions,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'waivers','[]'::jsonb));
select pg_temp.pg_act('offer',jsonb_build_object('offers',jsonb_build_array(jsonb_build_object('raceId',(select progression#>>'{definitions,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'classId','blizzardmancer','waivers','[]'::jsonb))));
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','[]'::jsonb));
select pg_temp.pg_assert((select stat_baseline#>>'{strength,base}'='21'and third_floor#>>'{selected,raceId}'='manual'and third_floor#>>'{selected,move}'='25'and third_floor#>>'{selected,size}'='2'and progression#>>'{selection,race,name}'='Tiny Fast Golem'and progression#>>'{selection,race,notes}'like'%Party bell%'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Approved custom mechanics or manual rulings were lost.');
select pg_temp.pg_assert(not exists(select 1 from public.dcc_crawlers,lateral jsonb_array_elements(learned_skills)where id=current_setting('dcc_test.pg_id')::uuid and value->>'id'='dagger'),'Custom detriment did not remove a zero-rank Skill.');
rollback to custom_build;
savepoint rank_override;
reset role;
update public.dcc_crawlers set learned_skills=learned_skills||jsonb_build_array(dcc_private.progression_item('abilities','ice-blast')||'{"rank":9,"origin":"gm","marked":false}'::jsonb)where id=current_setting('dcc_test.pg_id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_act('offer','{"offers":[{"raceId":"human","classId":"blizzardmancer","waivers":["selection-rank-cap"]}]}');
select set_config('request.jwt.claim.sub','c1922222-2222-4222-8222-222222222222',true);
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','[]'::jsonb));
select pg_temp.pg_assert((select value->>'rank'='13'and value->>'maxRank'='20'from public.dcc_crawlers,lateral jsonb_array_elements(learned_skills)where id=current_setting('dcc_test.pg_id')::uuid and value->>'id'='ice-blast'),'Explicit GM rank waiver was ignored or applied incorrectly.');
rollback to rank_override;
savepoint stat_cap;
set local role authenticated;
select set_config('request.jwt.claim.sub','c1911111-1111-4111-8111-111111111111',true);
select pg_temp.pg_act('offer','{"offers":[{"raceId":"pocket-kuma","classId":"blizzardmancer","waivers":[]}]}');
select pg_temp.pg_act('select',jsonb_build_object('offerId',(select progression#>>'{offers,0,id}'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'choices','{}'::jsonb,'split','{}'::jsonb,'skip','[]'::jsonb));
reset role;
update public.dcc_crawlers set inventory=inventory||'[{"id":"c1944444-4444-4444-8444-444444444444","name":"Strong hat","kind":"gear","quantity":1,"notes":"","gearSlot":"head","location":"head","effect":"manual","bonuses":{"strength":10,"intelligence":0,"constitution":0,"dexterity":0,"charisma":0,"dr":0,"evade":0}}]'where id=current_setting('dcc_test.pg_id')::uuid;
select pg_temp.pg_assert((select stat_baseline#>>'{strength,base}'='10'and stat_baseline#>>'{strength,cap}'='10'and tutorial_profile#>>'{stats,strength,enhanced}'='10'from public.dcc_crawlers where id=current_setting('dcc_test.pg_id')::uuid),'Selected cap did not include equipment.');
rollback to stat_cap;
select 'PASS: custom budgets/Passive ranks, transaction rollback, combined allocation, inherited Primal benefits, protected Heal, independent splits and equipment-inclusive caps' as result;
rollback;
